/*
 * PXPlay Noto Sans Hebrew: the latin range of the "Merged Noto Sans" of noto_sans_regular_font.h
 * with Noto Sans Hebrew merged into it, which is what the overlay bakes its atlas from for the
 * hebrew locale. One typeface has to carry both, because nuklear bakes a font out of a single ttf
 * and merging two of them into one nk_font is not something its atlas can do per font size.
 *
 * The latin glyphs are the very ones the other locales get, outline for outline, advance for advance
 * and on the same vertical metrics, so nothing but hebrew looks any different. See ui_consts.h for
 * the range that is baked.
 *
 * Sources, both under the SIL Open Font License 1.1:
 *   Merged Noto Sans      the font of noto_sans_regular_font.h
 *   Noto Sans Hebrew 3.001  github.com/notofonts/notofonts.github.io
 *                           fonts/NotoSansHebrew/unhinted/ttf/NotoSansHebrew-Regular.ttf
 *
 * Generated, do not edit by hand: PSPlay/tools/build_hebrew_font.py of the psplay_pc repository.
 */

